def _bind_agg_item(item: _RefItem, schema: Schema, output_seen: set[str]) -> _BoundItem:
    func = item.func
    if item.arg == "":
        arg_index = -1
    else:
        try:
            arg_index = schema.index(item.arg)
        except KeyError:
            raise QueryValidationError(f"unknown column: {item.arg!r}") from None
    bound = _make_agg_bound_item(func, arg_index, schema)
    if bound.output_name in output_seen:
        raise QueryValidationError(f"duplicate result column: {bound.output_name!r}")
    output_seen.add(bound.output_name)
    return bound


def _make_agg_bound_item(func: str, arg_index: int, schema: Schema) -> _BoundItem:
    """Build the bound description of one aggregate call.

    Shared by the projection and HAVING binding; HAVING-only aggregates use
    the same canonical label even though they produce no output column.
    """
    if arg_index == -1:
        if func != "COUNT":
            raise QuerySyntaxError(f"{func} does not accept '*'")
        label = "COUNT(*)"
        arg_col = None
    else:
        arg_col = schema.columns[arg_index]
        # The result label uses the column name as spelled in the schema.
        label = f"{func}({arg_col.name})"

    if func == "COUNT":
        out_type, nullable = "int64", False
    elif func == "SUM":
        if arg_col.type not in ("int64", "float64"):
            raise QueryValidationError(
                f"SUM requires an int64 or float64 argument, got {arg_col.type}"
            )
        out_type, nullable = arg_col.type, True
    elif func == "AVG":
        if arg_col.type not in ("int64", "float64"):
            raise QueryValidationError(
                f"AVG requires an int64 or float64 argument, got {arg_col.type}"
            )
        out_type, nullable = "float64", True
    else:  # MIN / MAX accept all four existing types.
        out_type, nullable = arg_col.type, True
    return _BoundItem(
        "agg",
        output_name=label,
        func=func,
        arg_index=arg_index,
        arg_type=arg_col.type if arg_col is not None else "",
        out_type=out_type,
        nullable=nullable,
    )

